-- Workspaces from before the Draft interview play get it here; new workspaces get it from SeedDefaults (ADR 0122).
INSERT INTO plays (id, workspace_id, label, type, description, instructions, enabled, show_when_stage, excluded_project_ids, created_by, created_at, updated_at, builtin_key)
SELECT lower(hex(randomblob(16))), w.id, 'Draft interview', 'interview', 'Drafts answers to the Interview questions from this project''s follow sources, for a person to confirm.', 'Draft answers to this project''s Interview template from its follow sources, for the person to confirm on the project''s Interview page; the project, this run''s trail id, and the checkouts of its project sources are named below. Start by calling `memory_create` with the project id and `kind` `interview`: it returns the interview memory with its `questions` (the Interview template''s questions), its `answers` (round 0 answers the template''s questions, a skip is no answer), its `sources`, and its `drafts`. Read every source whose stance is follow: a path in the checkout you are running in, a doc with `doc_get`, a memory with `memory_get`, pasted text from its body, and another project through its memories and interview answers with `memory_list` and `memory_get`, plus its checkout when one is named below. Read a large source selectively: its table of contents or headings first, then only the passages a question needs. Never read a source whose stance is question and never draft from one; another run asks about those. Draft every template question with no answer or a skip that a follow source speaks to. Draft a question that already has an answer only where the sources now say something different from that answer, and leave every other answered question alone. A question no follow source speaks to gets no draft. Shape each draft like an answer: `selected` with the labels of the options it picks, `text` for what the options do not say, `source_ids` with the ids of the follow sources it came from, and `where`, one line of at most 500 characters saying where in them, such as practices/testing.md, Test error paths first. Save drafts with `memory_update` on the interview memory, in `drafts` with this run''s `trail_id`, as you find them rather than all at the end, so the page shows them while you work; a draft replaces its question''s earlier one. Never ask the person anything and never use a question tool: the person confirms drafts on the page. Do not change the memory''s body, its answers, or its sources. End with a one-line summary of how many questions you drafted and from which sources.', 1, NULL, '[]', '', strftime('%s','now'), strftime('%s','now'), 'interview-draft'
FROM workspaces w
WHERE NOT EXISTS (SELECT 1 FROM plays p WHERE p.workspace_id = w.id AND p.builtin_key = 'interview-draft');
